// api/upload-richmenu.ts
export default async function handler(req: any, res: any) {
  const ACCESS_TOKEN = process.env.LINE_CHANNEL_ACCESS_TOKEN || "";
  const RICH_MENU_ID = "richmenu-8a1e9b760db92b6f54b42981bae8a34e";

  try {
    const base64Data = "";
    const binaryData = Buffer.from(base64Data, 'base64');

    const uploadRes = await fetch(`https://api-data.line.me/v2/bot/richmenu/${RICH_MENU_ID}/content`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${ACCESS_TOKEN}`,
        "Content-Type": "image/png",
      },
      body: binaryData,
    });

    if (uploadRes.ok) {
      res.status(200).json({ success: true, message: "画像アップロード完了！LINEを確認してください。" });
    } else {
      const err = await uploadRes.text();
      res.status(500).json({ error: "アップロード失敗", detail: err });
    }
  } catch(e: any) {
    res.status(500).json({ error: e.message });
  }
}
